CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, owner_id uuid NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS boards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships (user_id uuid NOT NULL REFERENCES users(id), board_id uuid NOT NULL REFERENCES boards(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('owner','editor','viewer')), PRIMARY KEY (user_id, board_id));
CREATE TABLE IF NOT EXISTS invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), board_id uuid NOT NULL REFERENCES boards(id) ON DELETE CASCADE, email text NOT NULL, role text NOT NULL CHECK (role IN ('editor','viewer')), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS board_labels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), board_id uuid NOT NULL REFERENCES boards(id) ON DELETE CASCADE, name text NOT NULL, color text NOT NULL CHECK (color ~ '^#[0-9A-Fa-f]{6}$'), UNIQUE (board_id, name));
CREATE TABLE IF NOT EXISTS columns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), board_id uuid NOT NULL REFERENCES boards(id) ON DELETE CASCADE, name text NOT NULL, "order" double precision NOT NULL);
CREATE TABLE IF NOT EXISTS cards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), column_id uuid NOT NULL REFERENCES columns(id) ON DELETE CASCADE, title text NOT NULL, description text, "order" double precision NOT NULL, assignee_id uuid REFERENCES users(id), due_date timestamptz, labels jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refresh_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz);
